    Location: { type: 'object', properties: { type: { type: 'string', enum: ['integration', 'link', 'address', 'phone', 'attendeePhone'] }, integration: { type: 'string' }, link: { type: 'string' }, address: { type: 'string' }, phone: { type: 'string' }, public: { type: 'boolean' } } },
    EventType: { type: 'object', description: 'A session type as cal.com describes an event type.', required: ['id', 'slug', 'title', 'lengthInMinutes'], properties: { id: int('A stable integer from the slug.'), ownerId: { type: ['integer', 'null'] }, lengthInMinutes: { type: 'integer' }, title: { type: 'string' }, slug: { type: 'string', enum: slugs }, description: { type: 'string' }, locations: { type: 'array', items: ref('Location') }, bookingFields: { type: 'array', items: { type: 'object', additionalProperties: true } }, disableGuests: { type: 'boolean' }, slotInterval: { type: 'integer' }, minimumBookingNotice: int('Minutes.'), beforeEventBuffer: { type: 'integer' }, afterEventBuffer: { type: 'integer' }, metadata: { type: 'object', description: 'requires, below, weekly, monthly, scheduler, sku, record — the site\'s own rules.', additionalProperties: true }, price: { type: 'number' }, currency: { type: 'string' }, seatsPerTimeSlot: { type: ['integer', 'null'] }, users: { type: 'array', items: { type: 'object', additionalProperties: true } }, _links: { type: 'object', properties: { book: str('The booking page, /book/<slug>.') } } }, additionalProperties: true },
    Slot: { type: 'object', required: ['start'], properties: { start: { type: 'string', format: 'date-time' }, end: { type: 'string', format: 'date-time' } } },
    Attendee: { type: 'object', required: ['email'], properties: { name: { type: 'string' }, email: { type: 'string', format: 'email' }, timeZone: { type: 'string' }, language: { type: 'string' }, phoneNumber: { type: 'string' }, absent: { type: 'boolean' } } },
    Host: { type: 'object', properties: { id: { type: 'integer' }, name: { type: 'string' }, email: { type: 'string' }, username: { type: 'string' }, timeZone: { type: 'string' } } },
    Booking: { type: 'object', description: 'A booking as cal.com shapes one (2024-08-13).', required: ['uid', 'status', 'start', 'end'], properties: { id: { type: 'integer' }, uid: { type: 'string' }, title: { type: 'string' }, description: { type: 'string' }, hosts: { type: 'array', items: ref('Host') }, status: { type: 'string', enum: ['accepted', 'pending', 'rescheduled', 'cancelled', 'rejected'] }, cancellationReason: { type: 'string' }, rescheduledFromUid: { type: 'string' }, start: { type: 'string', format: 'date-time' }, end: { type: 'string', format: 'date-time' }, duration: { type: 'integer' }, eventTypeId: { type: ['integer', 'null'] }, eventType: { type: ['object', 'null'], properties: { id: { type: 'integer' }, slug: { type: 'string' } } }, meetingUrl: { type: ['string', 'null'] }, location: { type: 'string' }, absentHost: { type: 'boolean' }, createdAt: { type: 'string' }, updatedAt: { type: 'string' }, metadata: { type: 'object', additionalProperties: true }, attendees: { type: 'array', items: ref('Attendee') }, guests: { type: 'array', items: { type: 'string' } }, bookingFieldsResponses: { type: 'object', additionalProperties: true } }, additionalProperties: true },
