    SchedulingWebhook: { type: 'object', properties: { id: { type: 'integer' }, uid: { type: 'string' }, subscriberUrl: { type: 'string' }, triggers: { type: 'array', items: { type: 'string', enum: ['BOOKING_CREATED', 'BOOKING_RESCHEDULED', 'BOOKING_CANCELLED', 'BOOKING_REJECTED', 'MEETING_STARTED', 'MEETING_ENDED', 'BOOKING_NO_SHOW_UPDATED', 'RECORDING_READY'] } }, active: { type: 'boolean' }, payloadTemplate: { type: ['string', 'null'] }, eventTypeId: { type: ['integer', 'null'] }, userId: { type: ['integer', 'null'] }, createdAt: { type: 'string' }, updatedAt: { type: 'string' }, lastDeliveredAt: { type: ['string', 'null'] }, lastError: { type: ['string', 'null'] } } },
    SchedulingWebhookInput: { type: 'object', required: ['subscriberUrl', 'triggers'], properties: { subscriberUrl: { type: 'string' }, triggers: { type: 'array', items: { type: 'string' } }, active: { type: 'boolean' }, secret: str('Signs every delivery: X-Cal-Signature-256, HMAC-SHA256 hex of the raw body.'), payloadTemplate: { type: 'string' }, eventTypeId: { type: 'integer' } } },
