      post: { tags: ['Scheduling Webhooks'], summary: 'Subscribe', description: 'Every booking the site knows — native, or cal.com\'s re-emitted — delivered as cal.com delivers one, signed X-Cal-Signature-256; a failure retried on the next event.', operationId: 'createSchedulingWebhook', security: keyOnly, requestBody: { required: true, content: { 'application/json': { schema: ref('SchedulingWebhookInput') } } }, responses: { 201: json(env(ref('SchedulingWebhook')), 'Subscribed.'), ...errors } },
