      patch: { tags: ['Scheduling Webhooks'], summary: 'Update a webhook', operationId: 'updateSchedulingWebhook', security: keyOnly, parameters: [{ name: 'id', in: 'path', required: true, schema: { type: 'string' } }], requestBody: { required: true, content: { 'application/json': { schema: ref('SchedulingWebhookInput') } } }, responses: { 200: json(env(ref('SchedulingWebhook'))), ...errors } },
